#include "openconsole/ocg2.h"
#include "openconsole/sha256.h"
static uint16_t u16(const uint8_t*p){return (uint16_t)p[0]|((uint16_t)p[1]<<8);}
static uint32_t u32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static uint64_t u64(const uint8_t*p){uint64_t v=0;unsigned i;for(i=0;i<8;i++)v|=(uint64_t)p[i]<<(i*8);return v;}
static int range(size_t a,size_t n,size_t z){return a<=z&&n<=z-a;}
static int eq(const uint8_t*a,const uint8_t*b,size_t n){uint8_t d=0;while(n--)d|=*a++^*b++;return d==0;}
static uint8_t fold(uint8_t c){return c>='A'&&c<='Z'?(uint8_t)(c+32):c;}
static int feq(const uint8_t*a,size_t an,const uint8_t*b,size_t bn){size_t i;if(an!=bn)return 0;for(i=0;i<an;i++)if(fold(a[i])!=fold(b[i]))return 0;return 1;}
static int identity(const uint8_t*p,size_t n,int version){size_t i;if(!n||n>(version?32u:64u))return 0;for(i=0;i<n;i++){uint8_t c=p[i];if((c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_'||c=='-'||(version&&((c>='A'&&c<='Z')||c=='.'||c=='+')))continue;return 0;}return (version||((p[0]>='a'&&p[0]<='z')||(p[0]>='0'&&p[0]<='9')));}
static int path(const uint8_t*p,size_t n){size_t i,start=0;if(!n||n>240||p[0]=='/')return 0;for(i=0;i<n;i++){uint8_t c=p[i];if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='.'||c=='_'||c=='-'||c=='/'))return 0;if(c=='/'){if(i==start||(i-start==1&&p[start]=='.')||(i-start==2&&p[start]=='.'&&p[start+1]=='.'))return 0;start=i+1;}}if(start==n)return 0;if((n>=4&&fold(p[0])=='e'&&fold(p[1])=='f'&&fold(p[2])=='i'&&p[3]=='/')||(n>=6&&fold(p[0])=='g'&&fold(p[1])=='a'&&fold(p[2])=='m'&&fold(p[3])=='e'&&fold(p[4])=='s'&&p[5]=='/')||(n>=13&&feq(p,12,(const uint8_t*)".openconsole",12)&&p[12]=='/')||(n>=12&&feq(p,12,(const uint8_t*)"openconsole-",12)))return 0;return 1;}
static int role(uint16_t r){return r>=OC_OCG2_ROLE_MANIFEST&&r<=OC_OCG2_ROLE_ENTRY_ARM64;}
static int entry(const oc_ocg2_bundle*b,size_t at,oc_ocg2_entry*e,size_t*next){uint16_t pn;if(!range(at,56,b->index_size))return 0;pn=u16(b->index+at);if(!range(at+56,pn,b->index_size))return 0;e->path=b->index+at+56;e->path_size=pn;e->role=u16(b->index+at+2);e->offset=u64(b->index+at+8);e->size=u64(b->index+at+16);e->digest=b->index+at+24;if(e->offset>b->payload_size||e->size>b->payload_size-e->offset)return 0;e->data=b->payload+(size_t)e->offset;*next=at+56+pn;return 1;}
oc_ocg2_result oc_ocg2_parse(const uint8_t*x,size_t n,oc_ocg2_bundle*b){uint64_t il,pl,total,records,indexed_payload,previous_end=0;uint32_t count,gid,ver,manifest;uint8_t d[32];size_t at,i,j,next,current_next;oc_ocg2_entry e,prior;if(!x||!b||n<128||n>64u*1024u*1024u)return OC_OCG2_LIMIT;if(!eq(x,(const uint8_t*)"OCG2",4))return OC_OCG2_MAGIC;if(u16(x+4)!=2||u16(x+6))return OC_OCG2_VERSION;il=u64(x+16);pl=u64(x+24);count=u32(x+32);total=u64(x+40);if(u32(x+8)!=128||u32(x+12)||il>256u*1024u||count==0||count>256||u16(x+36)!=1||u16(x+38)!=114)return OC_OCG2_HEADER;for(i=112;i<128;i++)if(x[i])return OC_OCG2_HEADER;if(total!=n||il>SIZE_MAX||pl>SIZE_MAX||128u+114u+(size_t)il>n||pl!=n-(128u+114u+(size_t)il))return OC_OCG2_LENGTH;b->blob=x;b->size=n;b->signature=x+128;b->index=x+242;b->index_size=(size_t)il;b->payload=b->index+b->index_size;b->payload_size=(size_t)pl;b->bundle_id=x+48;b->publisher_key_id=x+80;b->count=count;if(!oc_sha256(b->index,b->index_size,d)||!eq(d,b->bundle_id,32))return OC_OCG2_INDEX_DIGEST;if(b->index_size<80||!eq(b->index,(const uint8_t*)"OCI2",4)||u16(b->index+4)!=2||u16(b->index+6)||u32(b->index+8)!=80)return OC_OCG2_INDEX;manifest=u32(b->index+16);gid=u32(b->index+20);ver=u32(b->index+24);records=u64(b->index+32);indexed_payload=u64(b->index+40);if(u32(b->index+12)!=count||u32(b->index+28)||indexed_payload!=pl||!eq(b->index+48,b->publisher_key_id,32)||!range(80,(size_t)gid+ver,b->index_size))return OC_OCG2_INDEX;b->game_id=b->index+80;b->game_id_size=gid;b->version=b->game_id+gid;b->version_size=ver;b->manifest_index=manifest;if(!identity(b->game_id,gid,0)||!identity(b->version,ver,1)||manifest>=count)return OC_OCG2_INDEX;at=80u+gid+ver;if(records>SIZE_MAX||!range(at,(size_t)records,b->index_size)||at+(size_t)records!=b->index_size)return OC_OCG2_INDEX;for(i=0;i<count;i++){b->offsets[i]=at;if(!entry(b,at,&e,&next))return OC_OCG2_OFFSET;current_next=next;if(!path(e.path,e.path_size))return OC_OCG2_PATH;if(!role(e.role)||u32(b->index+at+4))return OC_OCG2_ROLE;if(e.offset!=previous_end||e.size>32u*1024u*1024u)return OC_OCG2_OFFSET;if(i){size_t k,m=e.path_size<prior.path_size?e.path_size:prior.path_size;int cmp=0;for(k=0;k<m;k++)if(e.path[k]!=prior.path[k]){cmp=e.path[k]>prior.path[k]?1:-1;break;}if(!cmp)cmp=e.path_size>prior.path_size?1:(e.path_size<prior.path_size?-1:0);if(cmp<=0)return OC_OCG2_ORDER;}for(j=0;j<i;j++){if(!entry(b,b->offsets[j],&prior,&next))return OC_OCG2_INDEX;if(feq(e.path,e.path_size,prior.path,prior.path_size))return OC_OCG2_ORDER;}if(!oc_sha256(e.data,(size_t)e.size,d)||!eq(d,e.digest,32))return OC_OCG2_FILE_DIGEST;previous_end=e.offset+e.size;prior=e;at=current_next;}if(at!=b->index_size||previous_end!=pl)return OC_OCG2_INDEX;{unsigned manifests=0,entries=0;for(i=0;i<count;i++){if(!entry(b,b->offsets[i],&e,&next))return OC_OCG2_INDEX;if(e.role==OC_OCG2_ROLE_MANIFEST){manifests++;if(i!=manifest||e.path_size!=9||!eq(e.path,(const uint8_t*)"game.toml",9))return OC_OCG2_ROLE;}if(e.role==OC_OCG2_ROLE_ENTRY_X64||e.role==OC_OCG2_ROLE_ENTRY_ARM64)entries++;}if(manifests!=1||entries!=1)return OC_OCG2_ROLE;}return OC_OCG2_OK;}
oc_ocg2_result oc_ocg2_verify_signature(const oc_ocg2_bundle*b,const uint8_t key[57],oc_ocg2_ed448_verify verify,void*ctx,uint8_t*w,size_t cap){static const uint8_t domain[24]="OPENCONSOLE-OCG2-SIGNED";uint8_t d[32];size_t need,i;if(!b||!key||!verify||!w)return OC_OCG2_SIGNATURE;if(!oc_sha256(key,57,d)||!eq(d,b->publisher_key_id,32))return OC_OCG2_UNTRUSTED_KEY;need=24+128+b->index_size;if(cap<need)return OC_OCG2_LIMIT;for(i=0;i<24;i++)w[i]=domain[i];for(i=0;i<128;i++)w[24+i]=b->blob[i];for(i=0;i<b->index_size;i++)w[152+i]=b->index[i];return verify(ctx,key,w,need,b->signature)?OC_OCG2_OK:OC_OCG2_SIGNATURE;}
oc_ocg2_result oc_ocg2_find_role(const oc_ocg2_bundle*b,uint16_t r,oc_ocg2_entry*out){size_t i,n;for(i=0;b&&out&&i<b->count;i++){if(!entry(b,b->offsets[i],out,&n))return OC_OCG2_INDEX;if(out->role==r)return OC_OCG2_OK;}return OC_OCG2_NOT_FOUND;}
oc_ocg2_result oc_ocg2_find_path(const oc_ocg2_bundle*b,const char*p,uint16_t r,oc_ocg2_entry*out){size_t i,n=0,next;while(p&&p[n])n++;for(i=0;b&&out&&i<b->count;i++){if(!entry(b,b->offsets[i],out,&next))return OC_OCG2_INDEX;if(out->role==r&&out->path_size==n&&eq(out->path,(const uint8_t*)p,n))return OC_OCG2_OK;}return OC_OCG2_NOT_FOUND;}
oc_ocg2_result oc_ocg2_entry_at(const oc_ocg2_bundle*b,uint32_t index,oc_ocg2_entry*out){size_t next;if(!b||!out||index>=b->count)return OC_OCG2_NOT_FOUND;return entry(b,b->offsets[index],out,&next)?OC_OCG2_OK:OC_OCG2_INDEX;}
const char*oc_ocg2_result_code(oc_ocg2_result r){static const char*const n[]={"OCG2_OK","OCG2_LIMIT","OCG2_BAD_MAGIC","OCG2_UNSUPPORTED_VERSION","OCG2_BAD_HEADER","OCG2_LENGTH_MISMATCH","OCG2_INDEX_DIGEST","OCG2_UNTRUSTED_KEY","OCG2_BAD_SIGNATURE","OCG2_BAD_INDEX","OCG2_BAD_PATH","OCG2_BAD_ORDER","OCG2_BAD_ROLE","OCG2_BAD_OFFSET","OCG2_BAD_DIGEST","OCG2_NOT_FOUND","OCG2_MANIFEST_MISMATCH"};return(unsigned)r<sizeof(n)/sizeof(n[0])?n[r]:"OCG2_UNKNOWN";}
